# Router + pipeline with explicit, validated state transitions.
from enum import Enum

class S(str, Enum):
    PENDING = "pending"; ROUTED = "routed"; ANSWERED = "answered"; FAILED = "failed"

ALLOWED = {S.PENDING: {S.ROUTED, S.FAILED}, S.ROUTED: {S.ANSWERED, S.FAILED}}

def transition(run: dict, new: S) -> None:
    if new not in ALLOWED.get(run["state"], set()):
        raise ValueError(f"illegal {run['state']} -> {new}")
    run["state"] = new          # also persist: UPDATE workflow_run SET state=%s WHERE id=%s

def route(question: str) -> str:
    q = question.lower()
    if any(w in q for w in ("how many", "total", "top", "sum")):
        return "sql"
    if "policy" in q or "return" in q:
        return "rag"
    return "general"            # in practice: small classifier model with a JSON label

HANDLERS = {"sql": lambda q: "SQL pipeline", "rag": lambda q: "RAG pipeline", "general": lambda q: "chat"}

def handle(run: dict) -> str:
    branch = route(run["question"]); transition(run, S.ROUTED)
    answer = HANDLERS[branch](run["question"]); transition(run, S.ANSWERED)
    return answer
```

